(()=>{
 const colors=[['Yeşil','#285b49'],['Mavi','#2864be'],['Mor','#7754b4'],['Turuncu','#ad4e20'],['Pembe','#b03973'],['Turkuaz','#167c83']];
 const picker=document.querySelector('#accentPicker'),presets=document.querySelector('#colorPresets');
 function apply(color,persist=true){if(!/^#[0-9a-f]{6}$/i.test(color))return;const channels=color.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4),l=.2126*channels[0]+.7152*channels[1]+.0722*channels[2],ink=(l+.05)/.05>1.05/(l+.05)?'#101713':'#ffffff';document.documentElement.style.setProperty('--accent',color);document.documentElement.style.setProperty('--accent-ink',ink);document.documentElement.style.setProperty('--accent-label',color);document.documentElement.dataset.accent='custom';picker.value=color;presets.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===color)));if(persist)try{localStorage.setItem('ritim-accent',color)}catch{toast('Renk bu tarayıcıda kaydedilemedi.')}}
 presets.innerHTML=colors.map(([name,color])=>`<button type="button" data-color="${color}" aria-label="${name}" title="${name}" style="--swatch:${color}"><span></span>${name}</button>`).join('');
 presets.onclick=e=>{const b=e.target.closest('button');if(b)apply(b.dataset.color)};picker.oninput=()=>apply(picker.value);document.querySelector('#themeSettings').onclick=()=>document.querySelector('#themeDialog').showModal();document.querySelector('#resetAccent').onclick=()=>apply('#2864be');let color='#2864be';try{color=localStorage.getItem('ritim-accent')||color}catch{}apply(color,false);
})();

